def game_html():
    return gzip.decompress(base64.b85decode(_PAYLOAD)).decode("utf-8")

def main():
    if "--export-html" in sys.argv:
        from pathlib import Path
        Path("whiteout.html").write_text(game_html(), encoding="utf-8")
        print("Saved whiteout.html")
        return
    in_streamlit = False
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        in_streamlit = get_script_run_ctx(suppress_warning=True) is not None
    except ImportError:
        pass
    if in_streamlit:
        import streamlit as st
        import streamlit.components.v1 as components
        st.set_page_config(page_title="백야 · 설원 생존", page_icon="❄️", layout="wide", initial_sidebar_state="collapsed")
        st.markdown("<style>.block-container{padding:0!important;max-width:100%!important}header[data-testid=stHeader]{display:none}iframe{display:block;border:0}</style>", unsafe_allow_html=True)
        components.html(game_html(), height=780, scrolling=False)
        with st.expander("조작법 / 실행 도움말"):
            st.write("PC: WASD 이동, 화면 드래그로 시점 회전, 클릭 공격, E 사용, F 먹기, 1~4 도구 선택. 모바일: 왼쪽 스틱 이동, 화면 드래그로 시점 회전, 오른쪽 버튼 사용.")
            st.write("나무 옆에서 도끼 공격으로 장작을 모으세요. 불 옆에서 라이터를 들고 사용하면 불을 피웁니다. 프라이팬을 들고 사용하면 고기를 굽습니다. 집 구석의 손은 생고기 2개를 총알 3발과 바꿔 줍니다.")
            st.write("현재 판은 로우폴리 1인칭 생존 게임입니다. 최고 생존 기록만 브라우저에 저장되며, 진행 중인 상태는 새로고침하면 초기화됩니다. WebGL을 지원하는 브라우저가 필요합니다.")
    else:
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        import os
        page = game_html().encode("utf-8")
        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(page)))
                self.end_headers()
                self.wfile.write(page)
        port = int(os.environ.get("PORT", "8000"))
        print(f"백야 실행 중: http://localhost:{port} (종료: Ctrl+C)")
        try:
            ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()
        except KeyboardInterrupt:
            pass

if __name__ == "__main__":
    main()
